import json
import subprocess
import base64

# Create new module with 8 channels
subprocess.run(["ft2", "call", "module_new", json.dumps({
    "channels": 8,
    "name": "Keygen Dreams"
})], check=True)

# Set tempo and speed
subprocess.run(["ft2", "call", "song_set", json.dumps({
    "bpm": 150,
    "speed": 4,
    "length": 8,
    "loop_start": 0
})], check=True)

# Load samples into instruments
for i in range(1, 9):
    subprocess.run(["ft2", "call", "sample_load", json.dumps({
        "path": f"/workspace/sample_{i}.wav",
        "instrument": i,
        "sample": 0
    })], check=True)

    # Set instrument names
    names = {1: "Kick", 2: "Snare", 3: "Hat", 4: "OpenHat", 
             5: "Bass", 6: "Lead", 7: "Pad", 8: "Arp"}
    subprocess.run(["ft2", "call", "instrument_set", json.dumps({
        "instrument": i,
        "name": names[i]
    })], check=True)

# Set sample loop points for sustained instruments
# Bass, Lead, Pad, Arp should loop
for inst in [5, 6, 7, 8]:
    subprocess.run(["ft2", "call", "sample_set", json.dumps({
        "instrument": inst,
        "sample": 0,
        "loop_start": 0,
        "loop_length": 1000,  # Small loop for sustain
        "flags": 1  # Loop enabled
    })], check=True)

print("Module structure created, samples loaded")
